void RepairCustodyReceivedSource::swap(RepairCustodyReceivedSource&v){if(this==&v)return;auto left=copy_memory,right=v.copy_memory;auto both=CheckpointCopyLease::hold_both(left,right);copy_memory=both;v.copy_memory=both;using std::swap;swap(id,v.id);swap(contract_ref,v.contract_ref);swap(occurred_at,v.occurred_at);swap(actual_handover_source,v.actual_handover_source);swap(actual_item_selection,v.actual_item_selection);swap(actual_condition_head,v.actual_condition_head);swap(original_resource_effect_refs,v.original_resource_effect_refs);swap(actual_contact_source,v.actual_contact_source);swap(actual_actor_id,v.actual_actor_id);swap(actor_route,v.actor_route);swap(actual_transfer,v.actual_transfer);copy_memory=std::move(right);v.copy_memory=std::move(left);}
